/// 全应用共享的图标注册表。
///
/// 必须是 `static`——`IconSet::get` 返回 `&'static Icon`，而宿主侧的栅格化缓存
/// 以图标数据的**地址**为键。若注册表能随 `App` 析构，地址会被下一个图标复用，
/// 于是 A 的缓存条目会被 B 命中，表现为"某个图标显示成另一个"且不报错。
static ICONS: OnceLock<IconSet> = OnceLock::new();

fn icons() -> &'static IconSet {
    ICONS.get_or_init(|| {
        let mut set = IconSet::with_builtin();
        for (name, path_data) in APP_ICONS {
            set = set.with(name, IconSource::Path(path_data));
        }
        // 在启动路径上就把解析跑完：13 个图标的全命令集解析是一次性的，
        // 放这里意味着它落在启动里，而不是第一帧（那一帧会明显掉帧）。
        set.freeze();
        set
    })
}

/// 取已解析的图标数据。进程内首次调用时一次性解析全部注册表，之后零开销查询。
///
/// 未知名字回落到空图标（渲染为空白），不 panic——见 [`IconSet::get`]。
pub fn icon_data(name: &str) -> &'static Icon {
    icons().get(name)
}

/// 渲染图标（`size` 为逻辑像素边长，`color` 由调用点给定）。
pub fn icon<'a, Message: 'a>(name: &str, size: f32, color: Color) -> Element<'a, Message> {
    let icon = icon_data(name);
    let resolver = IconResolver::new(icons());
    match resolver.handle(icon, size, zephyra::core::Color {
        r: color.r,
        g: color.g,
        b: color.b,
        a: color.a,
    }) {
        // FilterMethod 默认 Linear：2x 栅格 → 逻辑尺寸由 GPU 双线性降采样
        Some(handle) => iced::widget::image(handle).width(size).height(size).into(),
        // 不可渲染（`fill="none"` 或解析失败）时画一块等大的空白占位。
        //
        // 刻意**不**退化成矢量路径填充：那条路每帧都要三角化，而图标在正常情况下
        // 全部命中纹理缓存。真的需要看形状时用 `zephyra_iced::icon::vector_path`。
        None => iced::widget::Space::new().width(size).height(size).into(),
    }
}